insert into public.changelog (datum, categorie, module, titel, omschrijving) values
  ('2026-08-05','verbeterd','Calculatie','Kolomnamen zelf instellen, totalen onder de groep',
   'Je kunt de kolomkoppen in de calculatie nu zelf een naam geven: dubbelklik op een kop, of pas ze aan in het menu Kolommen. Die namen gelden alleen voor jou en blijven bewaard. De koppen zijn bovendien niet meer vetgedrukt en lopen netjes door op een tweede regel in plaats van uit de kolom te lopen. De groepstotalen staan niet langer rechts in de gekleurde balk, maar in een eigen regel onder de groep, met elk bedrag onder de kolom waar het bij hoort.'),
  ('2026-08-05','verbeterd','Calculatie','Lange omschrijvingen volledig zichtbaar bij bewerken',
   'Klik je in een omschrijving die langer is dan de kolom breed is, dan schuift het veld uit naar rechts. Je ziet en bewerkt zo de hele tekst zonder de kolom breder te hoeven maken.'),
  ('2026-08-05','verbeterd','Calculatie','Meerdere regels tegelijk verslepen',
   'Selecteer je meerdere regels en pak je er één op, dan verplaats je ze voortaan allemaal tegelijk. Dat werkt binnen een groep, naar een andere groep, en door ze op een groepskop te laten vallen. Voorheen ging alleen de opgepakte regel mee.');
